def stdev(nums: List[float]) -> float:
    """ For a given list of input numbers, calculate Standard Deviation
    >>> stdev([1.0, 2.0, 3.0, 4.0])
    1.4142135623730951
    """
    mean = sum(nums) / len(nums)
    sum_squared_diff = 0
    for x in nums:
        sum_squared_diff += pow(x - mean, 2)
    return pow(sum_squared_diff / len(nums), 0.5)

