def _parse_nested_parens(paren_string: List[str]) -> List[int]:
    result = []

    for parens in paren_string:
        nested_count = 0
        if parens == '()':
            nested_count += 1

        for p in parens:
            if p == ')':
                nested_count -= 1

            if nested_count < 0:
                break

        result.append(nested_count)

    return result

