    """ Return reversed string with the innermost grouping of parentheses first.

    >>> reverse_parentheses('(()()) ((())) () ((())()())')
    '(())(())(()()())'
    """

    def reverse_parentheses_helper(paren_string: str) -> str:
        reverse_parens = []

        for paren in paren_string:
            if paren == '(':
                reverse_parens.append(')')
            elif paren == ')':
                reverse_parens.append('(')
        return ''.join(reverse_parens)

    reversed_string = reverse_parentheses_helper(paren_string)

    while '(' in reversed_string:
        parentheses = [paren for paren in reversed_string if paren == '(']

        reversed_string = reverse_parentheses_helper(''.join(parentheses))

        while ')':
            parentheses = [paren for paren in reversed_string if paren == ')']

