def parse_nested_parens_bracket(paren_string: str) -> int:
    if len(paren_string) == 0:
        return 0
    last = paren_string[-1]
    if last == ')':
        return 0
    bracket_level = 0
    for bracket in paren_string:
        if bracket == '(':
            bracket_level += 1
        elif bracket == ')':
            bracket_level -= 1
    return bracket_level + parse_nested_parens_bracket(paren_string[:-1])


