def count_nested_parens(paren_string: str) -> int:
    """ Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> count_nested_parens('(()()) ((())) () ((())

    result = []
    paren_groups = [int(paren_group) for paren_group in paren_string.split(' ') if paren_group]
    print('paren groups', paren_groups)
    for index, paren_group in enumerate(paren_groups, 1):
        group_level = 1
        inner_levels = [paren_group]
        while len(inner_levels) > 0:
            current_level = inner_levels.pop()
            if current_level < paren_group:
                inner_levels.append(current_level + 1)
            else:
                group_level += 1
                inner_levels.append(current_level + 1)

        if group_level > result[-1]:
            result.append(group_level)
    return result


