def parse_group(paren_group: str) -> List[str]:
    """ Input to this function is a list of balanced nested paren strings. Your goal is to convert this list
    into a list of words by removing all the parens.
    Only valid groups are returned. For invalid groups the function raises exception. Valid groups are balanced
    and non-nested within each other.
    >>> parse_group(separate_paren_groups('( ) (( )) (( )( ))'))
    ['This', 'is', 'a', 'Test']
    """
    words = []
    current_group = ''
    for char in paren_group:
        if char == '(':
            if current_group != '':
                words.append(current_group)
            current_group = ''
        elif char == ')':
            words.append(current_group)
            current_group = ''
        else:
            current_group += char
    words.append(current_group)
    return words


