def mean_squared_deviation(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate Mean Squared Deviation
    around the mean of this dataset.
    Mean Squared Deviation is the average of squared deviations from a
    centerpoint (mean in this case):
    MSD = average | x - x_mean | ** 2
    >>> mean_squared_deviation([1.0, 2.0, 3.0, 4.0])
    2.5
    """
    x_mean = sum(numbers)/float(len(numbers))
    if x_mean == 0:
        return 0.0
    else:
        deviations = [(x - x_mean) for x in numbers]
        return sum([(x - x_mean)**2 for x in deviations]) / float(len(numbers))


